    n, m = len(grid), len(grid[0])
    # Complete the colored diagonal bands by repeating their diagonal-color cycle.
    obs = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                obs[c-r] = v
    # Infer a repeating offset cycle from periodic matches among observed streaks.
    # For these tasks the filled pattern has one color per c-r diagonal.
    keys = sorted(obs)
    period = max(keys)-min(keys)+1
    for p in range(1, period+1):
        if all(obs[a] == obs[b] for a in keys for b in keys if (a-b) % p == 0):
            period = p
            break
    residues = {}
    for d,v in obs.items():
        residues[d % period] = v
    # Missing residue colors are interpolated in the order of known diagonal marks.
    ordered = sorted(obs)
    for d in range(min(keys), max(keys)+1):
        if d % period not in residues:
            nearest = min(ordered, key=lambda x: abs(x-d))
            residues[d % period] = obs[nearest]
    return [[residues[(c-r) % period] for c in range(m)] for r in range(n)]
